    "4c2ed27d": {"text":"Tutor: {name}","hash":"h1-5694c375"},
    "4c310e4f": {"text":"Partita","hash":"h1-f46da8da"},
    "4c4555c3": {"text":"☪ {realm} rivendica l'ufficio vacante di {title}.","hash":"h1-58c9bac7"},
