    "756b1ae3": {"text":"Ragionalo.","hash":"h1-f1153c8b"},
    "75790d2b": {"text":"Regno di Pamplona","hash":"h1-5652747f"},
    "757cd274": {"text":"Ascolta e prendi appunti.","hash":"h1-1e762bab"},
