    "78aea6d0": {"forms":{"select":"value","param":"focus","cases":{"dip":"Uno sconosciuto di vera realizzazione in diplomazia.","mar":"Uno sconosciuto di grande talento nelle questioni marziali.","ste":"Uno sconosciuto di reale realizzazione nell'amministrazione.","int":"Uno sconosciuto di vera realizzazione negli intrighi.","lea":"Uno sconosciuto di reale realizzazione nell'apprendimento.","other":"Uno sconosciuto di vera realizzazione."}},"hash":"h1-905634d0"},
